<?php
$pdo=db();$canManage=in_array($user['role'],['Administrator','Head','Clerk'],true);$query=trim((string)($_GET['q']??''));$form=filter_var($_GET['form']??null,FILTER_VALIDATE_INT);$editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT);$editBook=null;
try {
if($editId&&$canManage){$s=$pdo->prepare('SELECT * FROM library_books WHERE id=:id');$s->execute(['id'=>$editId]);$editBook=$s->fetch()?:null;}
$q='%'.$query.'%';$bookStmt=$pdo->prepare("SELECT b.*,b.total_copies-COALESCE(x.on_loan,0) AS available_copies,COALESCE(x.on_loan,0) AS on_loan FROM library_books b LEFT JOIN (SELECT book_id,COUNT(*) AS on_loan FROM library_loans WHERE returned_on IS NULL GROUP BY book_id) x ON x.book_id=b.id WHERE (:q='' OR b.title LIKE :title OR b.author LIKE :author OR COALESCE(b.isbn,'') LIKE :isbn OR COALESCE(b.subject_area,'') LIKE :subject) ORDER BY b.active DESC,b.title LIMIT 300");$bookStmt->execute(['q'=>$query,'title'=>$q,'author'=>$q,'isbn'=>$q,'subject'=>$q]);$books=$bookStmt->fetchAll();
$loans=[];if($canManage){$loanStmt=$pdo->prepare("SELECT l.*,b.title,b.author,b.shelf_location,s.admission_no,s.first_name,s.last_name,issuer.full_name AS issuer FROM library_loans l JOIN library_books b ON b.id=l.book_id JOIN students s ON s.id=l.student_id LEFT JOIN users issuer ON issuer.id=l.issued_by WHERE (:q='' OR b.title LIKE :title OR s.first_name LIKE :first OR s.last_name LIKE :last OR s.admission_no LIKE :admission) ORDER BY (l.returned_on IS NULL) DESC,l.due_on,l.id DESC LIMIT 300");$loanStmt->execute(['q'=>$query,'title'=>$q,'first'=>$q,'last'=>$q,'admission'=>$q]);$loans=$loanStmt->fetchAll();}
$stats=$pdo->query("SELECT COUNT(*) AS titles,COALESCE(SUM(total_copies),0) AS copies,(SELECT COUNT(*) FROM library_loans WHERE returned_on IS NULL) AS on_loan,(SELECT COUNT(*) FROM library_loans WHERE returned_on IS NULL AND due_on<CURDATE()) AS overdue FROM library_books WHERE active=1")->fetch();
} catch (Throwable $e) { error_log('Library page failed: '.$e->getMessage()); echo '<section class="panel settings-panel"><h1>Library setup required</h1><p>The catalog tables are not available. An administrator should import <code>database/migrations/010_library.sql</code> into the school database, then reload this page.</p></section>'; return; }
$learners=[];if($form&&$form>=1&&$form<=6){$formQuery=$pdo->prepare("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' AND form_level=:form ORDER BY stream,last_name,first_name");$formQuery->execute(['form'=>$form]);$learners=$formQuery->fetchAll();}else{$learners=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' ORDER BY form_level,stream,last_name,first_name LIMIT 1000")->fetchAll();}
?>
<div class="page-heading"><div><div class="eyebrow">LEARNING RESOURCES</div><h1>School library</h1><p class="subheading">Maintain the book catalog and track learner borrowing and returns.</p></div></div>
<section class="stat-strip"><div><span>Active titles</span><b><?= number_format((int)$stats['titles']) ?></b></div><div><span>Catalog copies</span><b><?= number_format((int)$stats['copies']) ?></b></div><div><span>Currently on loan</span><b><?= number_format((int)$stats['on_loan']) ?></b></div><div><span>Overdue</span><b><?= number_format((int)$stats['overdue']) ?></b></div></section>
<section class="panel learners-panel"><form class="list-toolbar" method="get"><input type="hidden" name="page" value="library"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($query) ?>" placeholder="Search books, subjects or learners" aria-label="Search library"></div><div class="toolbar-right"><button class="outline-button">Search</button><?php if($query!==''): ?><a class="outline-button" href="?page=library">Clear</a><?php endif; ?></div></form></section>
<?php if($canManage): ?>
<section class="panel settings-panel"><h2><?= $editBook?'Edit catalog record':'Add a book to the catalog' ?></h2><p>Record the number of physical copies held. Copy counts cannot be reduced below the number currently on loan.</p><form method="post" action="actions/library_book_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><?php if($editBook): ?><input type="hidden" name="book_id" value="<?= (int)$editBook['id'] ?>"><?php endif; ?><label>Title<input name="title" required maxlength="180" value="<?= h($editBook['title']??'') ?>"></label><label>Author<input name="author" required maxlength="160" value="<?= h($editBook['author']??'') ?>"></label><label>ISBN <span class="optional">Optional</span><input name="isbn" maxlength="20" value="<?= h($editBook['isbn']??'') ?>"></label><label>Subject / category<input name="subject_area" maxlength="100" value="<?= h($editBook['subject_area']??'') ?>" placeholder="Mathematics, Biology…"></label><label>Publisher<input name="publisher" maxlength="160" value="<?= h($editBook['publisher']??'') ?>"></label><label>Shelf / location<input name="shelf_location" maxlength="60" value="<?= h($editBook['shelf_location']??'') ?>"></label><label>Publication year<input type="number" name="publication_year" min="1400" max="<?= (int)date('Y') ?>" value="<?= h($editBook['publication_year']??'') ?>"></label><label>Number of copies<input type="number" name="total_copies" min="1" max="9999" value="<?= h($editBook['total_copies']??'1') ?>" required></label><?php if($editBook): ?><label class="checkbox-label"><input type="checkbox" name="active" value="1" <?= $editBook['active']?'checked':'' ?>> Available in catalog for new loans</label><?php endif; ?><button class="primary-button"><?= $editBook?'Save book':'Add book' ?></button><?php if($editBook): ?><a class="outline-button" href="?page=library">Cancel edit</a><?php endif; ?></form></section>
<?php if($books): ?><section class="panel settings-panel"><h2>Issue a book</h2><p>Only active learners and available catalog copies can be selected. Due dates must be today or later.</p><form method="get" class="compact-form"><input type="hidden" name="page" value="library"><label>Filter learner list by form<select name="form"><option value="">All forms</option><?php for($f=1;$f<=6;$f++): ?><option value="<?= $f ?>" <?= $form===$f?'selected':'' ?>>Form <?= $f ?></option><?php endfor; ?></select></label><button class="outline-button">Filter learners</button></form><form method="post" action="actions/library_issue.php" class="compact-form"><?= csrf_field() ?><label>Available book<select name="book_id" required><option value="">Select title</option><?php foreach($books as $b): if($b['active']&&(int)$b['available_copies']>0): ?><option value="<?= (int)$b['id'] ?>"><?= h($b['title'].' — '.$b['author'].' ('.$b['available_copies'].' available)') ?></option><?php endif; endforeach; ?></select></label><label>Learner<select name="student_id" required><option value="">Select active learner</option><?php foreach($learners as $l): ?><option value="<?= (int)$l['id'] ?>"><?= h('Form '.$l['form_level'].($l['stream']?' '.$l['stream']:'').' · '.$l['first_name'].' '.$l['last_name'].' ('.$l['admission_no'].')') ?></option><?php endforeach; ?></select></label><label>Due date<input type="date" name="due_on" min="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d',strtotime('+14 days'))) ?>" required></label><label>Notes <span class="optional">Optional</span><input name="notes" maxlength="255"></label><button class="primary-button">Issue book</button></form></section><?php endif; ?>
<?php endif; ?>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Book catalog</h2><p><?= count($books) ?> record<?= count($books)===1?'':'s' ?> shown · maximum 300 per search</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Title / author</th><th>ISBN</th><th>Subject / shelf</th><th>Copies</th><th>Status</th><?php if($canManage): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($books as $b): ?><tr><td><b><?= h($b['title']) ?></b><br><span class="muted-cell"><?= h($b['author']) ?><?= $b['publisher']?' · '.h($b['publisher']):'' ?></span></td><td><?= h($b['isbn']?:'—') ?></td><td><?= h($b['subject_area']?:'—') ?><br><span class="muted-cell"><?= h($b['shelf_location']?:'') ?></span></td><td><?= (int)$b['available_copies'] ?> available / <?= (int)$b['total_copies'] ?></td><td><span class="status-pill"><?= $b['active']?'Active':'Archived' ?></span></td><?php if($canManage): ?><td><a class="outline-button compact-button" href="?page=library&edit=<?= (int)$b['id'] ?>">Edit</a></td><?php endif; ?></tr><?php endforeach; if(!$books): ?><tr><td colspan="<?= $canManage?6:5 ?>" class="empty-cell">No library titles match.<?php if($canManage): ?> Add a book above to begin the catalog.<?php endif; ?></td></tr><?php endif; ?></tbody></table></div></section>
<?php if($canManage): ?><section class="panel learners-panel"><div class="panel-heading"><div><h2>Loan register</h2><p>Open loans appear first, including overdue books. Up to 300 most recent matches are shown.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Book</th><th>Learner</th><th>Issued</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($loans as $l): $overdue=$l['returned_on']===null&&$l['due_on']<date('Y-m-d'); ?><tr><td><?= h($l['title']) ?><br><span class="muted-cell"><?= h($l['author']) ?></span></td><td><?= h($l['first_name'].' '.$l['last_name']) ?><br><span class="muted-cell"><?= h($l['admission_no']) ?></span></td><td><?= h(date('d M Y',strtotime($l['issued_on']))) ?></td><td><?= h(date('d M Y',strtotime($l['due_on']))) ?></td><td><?= $l['returned_on']?'Returned '.h(date('d M Y',strtotime($l['returned_on']))):($overdue?'<span class="consent-pill pending">Overdue</span>':'On loan') ?></td><td><?php if(!$l['returned_on']): ?><form method="post" action="actions/library_return.php" onsubmit="return confirm('Record this book as returned today?')"><?= csrf_field() ?><input type="hidden" name="loan_id" value="<?= (int)$l['id'] ?>"><button class="outline-button compact-button">Record return</button></form><?php endif; ?></td></tr><?php endforeach; if(!$loans): ?><tr><td colspan="6" class="empty-cell">No loans are recorded<?= $query!==''?' for this search':'' ?>.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
